from pathlib import Path

core = Path("core/core-rule-full.md")
s = core.read_text(encoding="utf-8")
old = """有人の高脅威目標の生命点が1になった時点で、その高脅威目標の撤退条件も同時に成立した場合は、撤退を処理する直前に【ネゴシエーション】を1度だけ使用できます。成功した場合は通常どおり【捕虜】または【鹵獲】として処理し、その対象の撤退は発生しません。失敗した場合は、そのまま撤退を処理します。  
この技能は、狂信的な敵や任務遂行のみを目的とする一部の敵には効果を発揮しません。  
"""
new = """有人の高脅威目標の生命点が1になった時点で、その高脅威目標の撤退条件も同時に成立した場合は、撤退を処理する直前に【ネゴシエーション】を1度だけ使用できます。成功した場合は通常どおり【捕虜】または【鹵獲】として処理し、その対象の撤退は発生しません。失敗した場合は、そのまま撤退を処理します。  
【ネゴシエーション】を使用できるのは、同一の対象に対して1戦闘につき1回だけです。通常の戦闘中、敵戦闘集団の撤退時、高脅威目標の撤退直前のいずれの使用機会も、この1回を共有します。一度【ネゴシエーション】を使用して失敗した対象には、その戦闘中は再び使用できません。複数の対象が存在する場合は、それぞれの対象について1回ずつ使用できます。  
この技能は、狂信的な敵や任務遂行のみを目的とする一部の敵には効果を発揮しません。  
"""
if s.count(old) != 1:
    raise SystemExit(f"core anchor count={s.count(old)}")
s = s.replace(old, new, 1)
core.write_text(s, encoding="utf-8")

decisions = Path("docs/CORE_V1_01_P0_DECISIONS.md")
d = decisions.read_text(encoding="utf-8")
heading = "## 14. 【ネゴシエーション】の撤退処理と再試行制限 — 承認・反映済み"
section = """

## 14. 【ネゴシエーション】の撤退処理と再試行制限 — 承認・反映済み

ユーザー判断により、【ネゴシエーション】と撤退が競合する場合の処理順、および同一対象への再試行を次のように整理する。

- 有人の高脅威目標が生命点1になった時点で撤退条件も同時に成立した場合、撤退処理の直前に【ネゴシエーション】を1回使用できる。
- 成功した場合は通常どおり【捕虜】または【鹵獲】として処理し、その対象は撤退しない。失敗した場合はそのまま撤退する。
- 【ネゴシエーション】は同一対象に対して1戦闘につき1回だけ使用できる。
- 通常の戦闘中、敵戦闘集団の撤退時、高脅威目標の撤退直前に生じる使用機会は、すべて同じ1回制限を共有する。
- 一度失敗した対象には、その戦闘中は再試行できない。
- 複数の対象が存在する場合は、各対象について1回ずつ使用できる。各使用には通常どおり指揮点1点を消費する。
- 【ネゴシエーション】対象外の敵・無人対象、およびシナリオ固有の禁止指定は従来どおり優先する。

これにより、指揮点を複数消費して同じ対象へ成功するまで連続試行する運用を防ぎ、捕虜化・鹵獲の成功判定とHP1で攻撃を止める判断に意味を持たせる。
"""
if heading not in d:
    d = d.rstrip() + section + "\n"
decisions.write_text(d, encoding="utf-8")

audit = Path("docs/SCENARIO_V1_01_RESOURCE_BALANCE_AUDIT.md")
a = audit.read_text(encoding="utf-8")
heading2 = "## 55. Core【ネゴシエーション】同一対象への再試行制限 — 採用済み"
section2 = """

## 55. Core【ネゴシエーション】同一対象への再試行制限 — 採用済み

ユーザー承認により、【ネゴシエーション】は同一対象に対して1戦闘につき1回だけ使用できるものとする。

- 通常の戦闘中に使用して失敗した対象へ、その戦闘中に再試行することはできない。
- 敵戦闘集団の撤退時、および有人高脅威目標の撤退直前に生じる使用機会も、同一対象についてはこの1回に含める。
- したがって、先に通常の【ネゴシエーション】へ失敗した対象が後から撤退条件を満たしても、撤退時に2回目の試行はできない。
- 複数の対象が存在する戦闘では、対象ごとに1回ずつ試行できる。
- Black Sun 3周目最終戦の対戦車砲装甲車両についても、HP1での鹵獲判定は1回限りとなる。失敗後に指揮点を追加消費して軍票+5の鹵獲報酬を再度狙うことはできない。

これにより、【ネゴシエーション】の判定失敗と指揮点消費に実質的なリスクを持たせ、捕虜・鹵獲ルートが成功するまでの反復判定になることを防ぐ。
"""
if heading2 not in a:
    a = a.rstrip() + section2 + "\n"
audit.write_text(a, encoding="utf-8")
